const listBuildCreations = `-- name: ListBuildCreations :many
SELECT id, workspace_id, creator_user_id, child_profile_id, session_id, title, prompt, archetype, recipe, build_plan, validation, ldraw_mpd, created_at, updated_at, inventory_snapshot, current_step, completed_at, progress_revision FROM build_creation
WHERE workspace_id = $1
  AND creator_user_id = $2
  AND ($3::uuid IS NULL OR child_profile_id = $3)
ORDER BY created_at DESC
LIMIT $5 OFFSET $4
`

type ListBuildCreationsParams struct {
	WorkspaceID    pgtype.UUID `json:"workspace_id"`
	CreatorUserID  pgtype.UUID `json:"creator_user_id"`
	ChildProfileID pgtype.UUID `json:"child_profile_id"`
	PageOffset     int32       `json:"page_offset"`
	PageSize       int32       `json:"page_size"`
}

func (q *Queries) ListBuildCreations(ctx context.Context, arg ListBuildCreationsParams) ([]BuildCreation, error) {
	rows, err := q.db.Query(ctx, listBuildCreations,
		arg.WorkspaceID,
		arg.CreatorUserID,
		arg.ChildProfileID,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BuildCreation{}
	for rows.Next() {
		var i BuildCreation
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.CreatorUserID,
			&i.ChildProfileID,
			&i.SessionID,
			&i.Title,
			&i.Prompt,
			&i.Archetype,
			&i.Recipe,
			&i.BuildPlan,
			&i.Validation,
			&i.LdrawMpd,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.InventorySnapshot,
			&i.CurrentStep,
			&i.CompletedAt,
			&i.ProgressRevision,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockBuildActorCapacity = `-- name: LockBuildActorCapacity :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// Serialize the active-build count and insert for one parent/child actor. This
// keeps the two-active-build limit exact under concurrent/retried requests
// without blocking a sibling profile or another family.
func (q *Queries) LockBuildActorCapacity(ctx context.Context, actorKey string) error {
	_, err := q.db.Exec(ctx, lockBuildActorCapacity, actorKey)
	return err
}

